//00writea.rs
fn main() - i32 {
    for i in 0..HEIGHT {
        for  in 0..WIDTH {
            print!("A");
        }
        println!(" [{}/{}]", i + 1, HEIGHT);
        yield(); //放弃处理器 
    }
    println!("Test writea OK!");
    0
}

yield系统调用  

 Rust
const SYSCALLYIELD: usize = 124;
pub fn sysyield() - isize {
    syscall(SYSCALLYIELD, [0, 0, 0])
}
pub fn yield() - isize {
    sysyield()
}

