协作式调度
- sysyield和sysexit系统调用
pub fn sysyield() - isize {
    suspendcurrentandrunnext();
    0
}
pub fn sysexit(exitcode: i32) - ! {
    println!("[kernel] Application exited with code {}", exitcode);
    exitcurrentandrunnext();
    panic!("Unreachable in sysexit!");
}

协作式调度

- sysyield和sysexit系统调用

// os/src/task/mod.rs

pub fn suspendcurrentandrunnext() {
    markcurrentsuspended();
    runnexttask();
}

pub fn exitcurrentandrunnext() {
    markcurrentexited();
    runnexttask();
}

