时钟中断与计时器
- 设置时钟中断
// os/src/sbi.rs
pub fn settimer(timer: usize) {
     sbicall(SBISETTIMER, timer, 0, 0);
 }
// os/src/timer.rs
pub fn setnexttrigger() {
    settimer(gettime() + CLOCKFREQ / TICKSPERSEC);
}
pub fn rustmain() - ! {
    trap::enabletimerinterrupt();
    timer::setnexttrigger();
}

